// Normalizacion integral de mensajes entrantes de Evolution API / WhatsApp
const body = $input.item.json.body || $input.item.json;

let senderPhone = "";
let incomingText = "";
let senderName = "Cliente";
let messageType = "text";
let mediaUrl = "";
let isFromMe = false;

if (body.data) {
  const data = body.data;
  isFromMe = data.key?.fromMe || false;
  senderPhone = (data.key?.remoteJid || "").replace("@s.whatsapp.net", "");
  senderName = data.pushName || "Cliente";
  const msg = data.message || {};
  if (msg.conversation) {
    incomingText = msg.conversation;
  } else if (msg.extendedTextMessage?.text) {
    incomingText = msg.extendedTextMessage.text;
  } else if (msg.imageMessage) {
    messageType = "image";
    incomingText = msg.imageMessage.caption || "[Comprobante Transferencia]";
    mediaUrl = msg.imageMessage.url || "";
  }
} else if (body.entry && body.entry[0]?.changes?.[0]?.value?.messages?.[0]) {
  const msg = body.entry[0].changes[0].value.messages[0];
  senderPhone = msg.from;
  senderName = body.entry[0].changes[0].value.contacts?.[0]?.profile?.name || "Cliente";
  if (msg.type === "text") incomingText = msg.text.body;
  if (msg.type === "image") { messageType = "image"; incomingText = msg.image?.caption || "[Comprobante]"; }
} else {
  senderPhone = String(body.from || body.phone || "573015568904");
  incomingText = body.text || body.message || "";
  senderName = body.name || "Cliente";
  messageType = body.type || "text";
}

if (isFromMe) return [];

const normalizedText = incomingText.toLowerCase().trim();
const isStremioPairingCode = /^[A-Za-z0-9]{4,6}$/.test(normalizedText) && !["hola", "pago", "menu", "info", "si", "no"].includes(normalizedText);

return {
  senderPhone,
  senderName,
  rawText: incomingText,
  normalizedText,
  messageType,
  mediaUrl,
  isStremioPairingCode
};

const item = $json;
const text = item.rawText;
const phone = item.senderPhone;
const name = item.senderName;

const refMatch = text.match(/M?\d{6,12}/i) || text.match(/ref[:\s]*([a-zA-Z0-9]+)/i);
const detectedRef = refMatch ? (refMatch[1] || refMatch[0]) : ("NEQ-" + Math.floor(100000 + Math.random() * 900000));

const responseText = "✦ *VIDEM | Comprobante Recibido*\n\nHola " + name + ", hemos recibido tu soporte de transferencia (Ref: *" + detectedRef + "*).\n\n⏳ *Validando transacción en red bancaria...*\nEn menos de 60 segundos se generará tu cuenta maestra y el kit de enlace de tu Smart TV.\n\nPor favor mantén este chat abierto.";

return {
  senderPhone: phone,
  senderName: name,
  transactionRef: detectedRef,
  paymentMethod: "Nequi / Transferencia",
  amount: "240000 COP ($60 USD)",
  plan: "Semestral (6 Meses)",
  paymentStatus: "Aprobado_Auto",
  responseText,
  triggerProvisioning: true
};

const item = $json;
const code = item.rawText.toUpperCase().trim();
const phone = item.senderPhone;
const name = item.senderName;

const activationUrl = "https://videm.tv/activar?code=" + code + "&nombre=" + encodeURIComponent(name);

const responseText = "✦ *VIDEM | Enlace de Pantalla Detectado*

📺 *Código:* `" + code + "`

Estamos vinculando tu perfil VIDEM con:
✔ CDN Dedicado 40-80 Mbps Remux activo
✔ HDR / Dolby Vision y Dolby Atmos habilitados
✔ Catálogo curado y depurado

⚡ *Autoriza tu pantalla con 1 clic aquí:*
👉 " + activationUrl + "

¡Tu televisor se sincronizará automáticamente! 🍿";

return { senderPhone: phone, senderName: name, stremioCode: code, responseText };

const phone = $json.senderPhone;
const name = $json.senderName;

const responseText = "✦ *VIDEM | Private Tech Concierge*

Hola " + name + ", un gusto saludarte. Soy el asistente técnico de *Videm*.

Para garantizarte la experiencia cinematográfica en *Remux 4K nativo, Dolby Vision y Dolby Atmos sin buffering*, validemos rápidamente tu equipamiento:

1️⃣ ¿Cuál es la marca y sistema de tu Smart TV o TV Box? (Ej: LG OLED webOS, Samsung Tizen, Google TV, Apple TV 4K, Fire TV Stick, Xiaomi Box).

2️⃣ ¿Cuentas con conexión de fibra óptica en casa? ¿De cuántos megas aproximadamente?

3️⃣ ¿Tienes barra de sonido o receptor A/V dedicado? (Ej: Sonos, Bose, Samsung Q-Symphony, etc.)

Puedes responder aquí mismo y evaluaremos tu perfil de inmediato.

_Nota: Al continuar autorizas el tratamiento de datos para fines de asistencia técnica y soporte._";

return { senderPhone: phone, senderName: name, responseText, flow: "diagnostico" };

const phone = $json.senderPhone;
const name = $json.senderName;

const responseText = "✦ *VIDEM | Portal de Clientes & Renovaciones*

Hola " + name + ", bienvenido a tu canal prioritario de servicio.

Para renovar tu enlace privado de inmediato:
1️⃣ Selecciona tu modalidad:
   • *Renovación Semestral (6 meses):* $240.000 COP
   • *Renovación Anual (12 meses):* $440.000 COP

2️⃣ Realiza tu pago mediante Nequi al *301 556 8904* o solicítanos el enlace PSE/Tarjeta y envía el comprobante por este chat.

Tu enlace CDN y addons se mantendrán activos sin necesidad de reconfigurar tu televisor.";

return { senderPhone: phone, senderName: name, responseText, flow: "renovacion" };

const phone = $json.senderPhone;
const name = $json.senderName;

const responseText = "✦ *VIDEM | Solicitud de Supresión de Datos Confirmada*

Hola " + name + ".

Hemos recibido formalmente tu solicitud de baja y supresión de datos conforme a la Ley 1581 de 2012 (Habeas Data).

Tu número telefónico y registro de contacto han sido retirados de nuestra lista de asistencia y no recibirás más notificaciones de Videm.

Si en el futuro deseas volver a disfrutar del estándar Videm en tu hogar, siempre serás bienvenido. ¡Que tengas un excelente día!";

return { senderPhone: phone, senderName: name, responseText, flow: "baja_datos" };

const payload = $input.item.json.body || $input.item.json;
let transactionRef = "";
let amount = 0;
let status = "";
let customerPhone = "";

if (payload.data && payload.data.transaction) {
  const tx = payload.data.transaction;
  transactionRef = tx.id || tx.reference;
  amount = (tx.amount_in_cents || 0) / 100;
  status = tx.status;
  customerPhone = tx.customer_data?.phone_number || tx.customer_email || "";
} else {
  transactionRef = payload.reference || ("TX-" + Date.now());
  status = payload.status || "APPROVED";
  amount = payload.amount || 240000;
  customerPhone = payload.phone || "573015568904";
}

if (status !== "APPROVED" && status !== "Aprobado_Auto") {
  return [];
}

return {
  senderPhone: customerPhone.replace(/[^0-9]/g, ""),
  senderName: "Cliente Videm",
  transactionRef,
  amount: amount + " COP",
  paymentMethod: "Pasarela Automatica",
  plan: "Semestral (6 Meses)",
  paymentStatus: "Aprobado",
  triggerProvisioning: true
};

const paymentData = $json;
const phone = paymentData.senderPhone;
const name = paymentData.senderName || "Apreciado Cliente";
const ref = paymentData.transactionRef;
const plan = paymentData.plan || "Semestral (6 Meses)";

const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const clientEmail = "videm.vip." + randomSuffix + "@videm.private";
const clientPass = "Videm4K." + randomSuffix + "!";

const now = new Date();
const expDate = new Date(now.getTime() + (180 * 24 * 60 * 60 * 1000));
const expDateFormatted = expDate.toLocaleDateString("es-CO", { year: "numeric", month: "long", day: "numeric" });
const activationUrl = "https://videm.tv/activar?nombre=" + encodeURIComponent(name) + "&plan=" + encodeURIComponent(plan);

const welcomeKitMessage = "✦ *¡FELICIDADES, " + name.toUpperCase() + "! TU ACCESO VIDEM ESTÁ ACTIVO* 🎬\n\nTu pago ha sido validado con éxito (Ref: *" + ref + "*).\nTu membresía *" + plan + "* se encuentra aprovisionada hasta el *" + expDateFormatted + "*.\n\n━━━━━━━━━━━━━━━━━━━━\n💎 *TUS CREDENCIALES PRIVADAS DE ACCESO:*\n📧 *Correo:* `" + clientEmail + "`\n🔑 *Contraseña:* `" + clientPass + "`\n━━━━━━━━━━━━━━━━━━━━\n\n📺 *CÓMO ACTIVAR TU SMART TV EN 60 SEGUNDOS:*\n\nEntra a tu portal VIP de activación interactiva:\n👉 " + activationUrl + "\n\nAllí solo debes ingresar el código de 4 letras que aparece en tu televisor y tu pantalla quedará calibrada con películas y series en Remux 4K nativo y Dolby Atmos. 🍿";

return {
  phone,
  name,
  plan,
  ref,
  clientEmail,
  clientPass,
  expDate: expDateFormatted,
  responseText: welcomeKitMessage,
  logEntry: {
    timestamp: new Date().toISOString(),
    phone,
    name,
    plan,
    ref,
    clientEmail,
    status: "Activo"
  }
};
